1	package org.jsoup.select;
2	
3	import org.jsoup.helper.Regex;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.helper.Validate;
6	import org.jsoup.nodes.CDataNode;
7	import org.jsoup.nodes.Comment;
8	import org.jsoup.nodes.DataNode;
9	import org.jsoup.nodes.LeafNode;
10	import org.jsoup.nodes.Node;
11	import org.jsoup.nodes.TextNode;
12	import org.jsoup.parser.TokenQueue;
13	import org.jspecify.annotations.Nullable;
14	
15	import java.util.function.Function;
16	import java.util.regex.Matcher;
17	import java.util.regex.Pattern;
18	
19	import static org.jsoup.select.StructuralEvaluator.ImmediateParentRun;
20	import static org.jsoup.internal.Normalizer.normalize;
21	
22	/**
23	 * Parses a CSS selector into an Evaluator tree.
24	 */
25	public class QueryParser implements AutoCloseable {
26	    private final static char[] Combinators = {'>', '+', '~'}; // ' ' is also a combinator, but found implicitly
27	    private final static String[] AttributeEvals = new String[]{"=", "!=", "^=", "$=", "*=", "~="};
28	    private final static char[] SequenceEnders = {',', ')'};
29	
30	    private final TokenQueue tq;
31	    private final String query;
32	    private boolean inNodeContext; // ::comment:contains should act on node value, vs element text
33	
34	    /**
35	     * Create a new QueryParser.
36	     * @param query CSS query
37	     */
38	    private QueryParser(String query) {
39	        Validate.notEmpty(query);
40	        query = query.trim();
41	        this.query = query;
42	        this.tq = new TokenQueue(query);
43	    }
44	
45	    /**
46	     Parse a CSS query into an Evaluator. If you are evaluating the same query repeatedly, it may be more efficient to
47	     parse it once and reuse the Evaluator.
48	
49	     @param query CSS query
50	     @return Evaluator
51	     @see Selector selector query syntax
52	     @throws Selector.SelectorParseException if the CSS query is invalid
53	     */
54	    public static Evaluator parse(String query) {
55	        try (QueryParser p = new QueryParser(query)) {
56	            return p.parse();
57	        } catch (IllegalArgumentException e) {
58	            throw new Selector.SelectorParseException(e.getMessage());
59	        }
60	    }
61	
62	    /**
63	     Parse the query. We use this simplified expression of the grammar:
64	     <pre>
65	     SelectorGroup   ::= Selector (',' Selector)*
66	     Selector        ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
67	     SimpleSequence  ::= [ TypeSelector ] ( ID | Class | Attribute | Pseudo )*
68	     Pseudo           ::= ':' Name [ '(' SelectorGroup ')' ]
69	     Combinator      ::= S+         // descendant (whitespace)
70	     | '>'       // child
71	     | '+'       // adjacent sibling
72	     | '~'       // general sibling
73	     </pre>
74	
75	     See <a href="https://www.w3.org/TR/selectors-4/#grammar">selectors-4</a> for the real thing
76	     */
77	    Evaluator parse() {
78	        Evaluator eval = parseSelectorGroup();
79	        tq.consumeWhitespace();
80	        if (!tq.isEmpty())
81	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
82	        return eval;
83	    }
84	
85	    Evaluator parseSelectorGroup() {
86	        // SelectorGroup. Into an Or if > 1 Selector
87	        Evaluator left = parseSelector();
88	        while (tq.matchChomp(',')) {
89	            Evaluator right = parseSelector();
90	            left = or(left, right);
91	        }
92	        return left;
93	    }
94	
95	    Evaluator parseSelector() {
96	        // Selector ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
97	        tq.consumeWhitespace();
98	
99	        Evaluator left;
100	        if (tq.matchesAny(Combinators)) {
101	            // e.g. query is "> div"; left side is root element
102	            left = new StructuralEvaluator.Root();
103	        } else {
104	            left = parseSimpleSequence();
105	        }
106	
107	        while (true) {
108	            char combinator = 0;
109	            if (tq.consumeWhitespace())
110	                combinator = ' ';            // maybe descendant?
111	            if (tq.matchesAny(Combinators)) // no, explicit
112	                combinator = tq.consume();
113	            else if (tq.matchesAny(SequenceEnders)) // , - space after simple like "foo , bar"; ) - close of :has()
114	                break;
115	
116	            if (combinator != 0) {
117	                Evaluator right = parseSimpleSequence();
118	                left = combinator(left, combinator, right);
119	            } else {
120	                break;
121	            }
122	        }
123	        return left;
124	    }
125	
126	    Evaluator parseSimpleSequence() {
127	        // SimpleSequence ::= TypeSelector? ( Hash | Class | Pseudo )*
128	        Evaluator left = null;
129	        tq.consumeWhitespace();
130	
131	        // one optional type selector
132	        if (tq.matchesWord() || tq.matches("*|"))
133	            left = byTag();
134	        else if (tq.matchChomp('*'))
135	            left = new Evaluator.AllElements();
136	
137	        // zero or more subclasses (#, ., [)
138	        while(true) {
139	            Evaluator right = parseSubclass();
140	            if (right != null) {
141	                left = and(left, right);
142	            }
143	            else break; // no more simple tokens
144	        }
145	
146	        if (left == null)
147	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
148	        return left;
149	    }
150	
151	    static Evaluator combinator(Evaluator left, char combinator, Evaluator right) {
152	        switch (combinator) {
153	            case '>':
154	                ImmediateParentRun run = left instanceof ImmediateParentRun ?
155	                    (ImmediateParentRun) left : new ImmediateParentRun(left);
156	                run.add(right);
157	                return run;
158	            case ' ':
159	                return and(new StructuralEvaluator.Ancestor(left), right);
160	            case '+':
161	                return and(new StructuralEvaluator.ImmediatePreviousSibling(left), right);
162	            case '~':
163	                return and(new StructuralEvaluator.PreviousSibling(left), right);
164	            default:
165	                throw new Selector.SelectorParseException("Unknown combinator '%s'", combinator);
166	        }
167	    }
168	
169	    @Nullable Evaluator parseSubclass() {
170	        //  Subclass: ID | Class | Attribute | Pseudo
171	        if      (tq.matchChomp('#'))    return byId();
172	        else if (tq.matchChomp('.'))    return byClass();
173	        else if (tq.matches('['))       return byAttribute();
174	        else if (tq.matchChomp("::"))   return parseNodeSelector(); // ::comment etc
175	        else if (tq.matchChomp(':'))    return parsePseudoSelector();
176	        else                            return null;
177	    }
178	
179	    /** Merge two evals into an Or. */
180	    static Evaluator or(Evaluator left, Evaluator right) {
181	        if (left instanceof CombiningEvaluator.Or) {
182	            ((CombiningEvaluator.Or) left).add(right);
183	            return left;
184	        }
185	        return new CombiningEvaluator.Or(left, right);
186	    }
187	
188	    /** Merge two evals into an And. */
189	    static Evaluator and(@Nullable Evaluator left, Evaluator right) {
190	        if (left == null) return right;
191	        if (left instanceof CombiningEvaluator.And) {
192	            ((CombiningEvaluator.And) left).add(right);
193	            return left;
194	        }
195	        return new CombiningEvaluator.And(left, right);
196	    }
197	
198	    private Evaluator parsePseudoSelector() {
199	        final String pseudo = tq.consumeCssIdentifier();
200	        switch (pseudo) {
201	            case "lt":
202	                return new Evaluator.IndexLessThan(consumeIndex());
203	            case "gt":
204	                return new Evaluator.IndexGreaterThan(consumeIndex());
205	            case "eq":
206	                return new Evaluator.IndexEquals(consumeIndex());
207	            case "has":
208	                return has();
209	            case "is":
210	                return is();
211	            case "contains":
212	                return contains(false);
213	            case "containsOwn":
214	                return contains(true);
215	            case "containsWholeText":
216	                return containsWholeText(false);
217	            case "containsWholeOwnText":
218	                return containsWholeText(true);
219	            case "containsData":
220	                return containsData();
221	            case "matches":
222	                return matches(false);
223	            case "matchesOwn":
224	                return matches(true);
225	            case "matchesWholeText":
226	                return matchesWholeText(false);
227	            case "matchesWholeOwnText":
228	                return matchesWholeText(true);
229	            case "not":
230	                return not();
231	            case "nth-child":
232	                return cssNthChild(false, false);
233	            case "nth-last-child":
234	                return cssNthChild(true, false);
235	            case "nth-of-type":
236	                return cssNthChild(false, true);
237	            case "nth-last-of-type":
238	                return cssNthChild(true, true);
239	            case "first-child":
240	                return new Evaluator.IsFirstChild();
241	            case "last-child":
242	                return new Evaluator.IsLastChild();
243	            case "first-of-type":
244	                return new Evaluator.IsFirstOfType();
245	            case "last-of-type":
246	                return new Evaluator.IsLastOfType();
247	            case "only-child":
248	                return new Evaluator.IsOnlyChild();
249	            case "only-of-type":
250	                return new Evaluator.IsOnlyOfType();
251	            case "empty":
252	                return new Evaluator.IsEmpty();
253	            case "blank":
254	                return new NodeEvaluator.BlankValue();
255	            case "root":
256	                return new Evaluator.IsRoot();
257	            case "scope":
258	                return new StructuralEvaluator.Scope();
259	            case "matchText": {
260	                @SuppressWarnings("deprecation") // :matchText remains supported until its scheduled removal.
261	                Evaluator.MatchText matchText = new Evaluator.MatchText();
262	                return matchText;
263	            }
264	            default:
265	                throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
266	        }
267	    }
268	
269	    // ::comment etc
270	    private Evaluator parseNodeSelector() {
271	        final String pseudo = tq.consumeCssIdentifier();
272	        inNodeContext = true;  // Enter node context
273	
274	        Evaluator left;
275	        switch (pseudo) {
276	            case "node":
277	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
278	                break;
279	            case "leafnode":
280	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
281	                break;
282	            case "text":
283	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
284	                break;
285	            case "comment":
286	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
287	                break;
288	            case "data":
289	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
290	                break;
291	            case "cdata":
292	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
293	                break;
294	            default:
295	                throw new Selector.SelectorParseException(
296	                    "Could not parse query '%s': unknown node type '::%s'", query, pseudo);
297	        }
298	
299	        // Handle following subclasses in node context (like ::comment:contains())
300	        Evaluator right;
301	        while ((right = parseSubclass()) != null) {
302	            left = and(left, right);
303	        }
304	
305	        inNodeContext = false;
306	        return left;
307	    }
308	
309	    private Evaluator byId() {
310	        String id = tq.consumeCssIdentifier();
311	        Validate.notEmpty(id);
312	        return new Evaluator.Id(id);
313	    }
314	
315	    private Evaluator byClass() {
316	        String className = tq.consumeCssIdentifier();
317	        Validate.notEmpty(className);
318	        return new Evaluator.Class(className.trim());
319	    }
320	
321	    private Evaluator byTag() {
322	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
323	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
324	        // consistency - both the selector and the element tag
325	        String tagName = normalize(tq.consumeElementSelector());
326	        Validate.notEmpty(tagName);
327	
328	        // namespaces:
329	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
330	            String plainTag = tagName.substring(2); // strip *|
331	            return new CombiningEvaluator.Or(
332	                new Evaluator.Tag(plainTag),
333	                new Evaluator.TagEndsWith(":" + plainTag)
334	            );
335	        } else if (tagName.endsWith("|*")) { // ns|*
336	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
337	            return new Evaluator.TagStartsWith(ns);
338	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
339	            tagName = tagName.replace("|", ":");
340	        }
341	
342	        return new Evaluator.Tag(tagName);
343	    }
344	
345	    private Evaluator byAttribute() {
346	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
347	            return evaluatorForAttribute(cq);
348	        }
349	    }
350	
351	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
352	        cq.consumeWhitespace();
353	        String key = consumeAttributeKey(cq);
354	        key = normalize(key);
355	        Validate.notEmpty(key);
356	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
357	        cq.consumeWhitespace();
358	        final Evaluator eval;
359	
360	        if (cq.isEmpty()) {
361	            if (key.startsWith("^"))
362	                eval = new Evaluator.AttributeStarting(key.substring(1));
363	            else if (key.equals("*")) // any attribute
364	                eval = new Evaluator.AttributeStarting("");
365	            else
366	                eval = new Evaluator.Attribute(key);
367	        } else if (cq.matchChomp("~=")) { // regex match; the remainder of the queue (less surrounding whitespace) is the pattern
368	            eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder().trim()));
369	        } else {
370	            final String op;
371	            if (cq.matchChomp("!=")) op = "!=";
372	            else if (cq.matchChomp("^=")) op = "^=";
373	            else if (cq.matchChomp("$=")) op = "$=";
374	            else if (cq.matchChomp("*=")) op = "*=";
375	            else if (cq.matchChomp("=")) op = "=";
376	            else throw new Selector.SelectorParseException(
377	                "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
378	
379	            cq.consumeWhitespace();
380	            final String rawValue = consumeAttributeValue(cq);
381	            final boolean quoted = !rawValue.isEmpty() && (rawValue.charAt(0) == '"' || rawValue.charAt(0) == '\'');
382	            // Quoted (CSS string) values keep their quotes and are decoded in the evaluator; bare values have their
383	            // CSS escapes decoded here, so escaped and unescaped forms of the same value match equally.
384	            final String value = quoted ? rawValue : TokenQueue.unescapeCss(rawValue);
385	            cq.consumeWhitespace();
386	
387	            // Quoted (CSS string) values compare case-sensitively by default; bare values keep jsoup's historical
388	            // case-insensitive compare. An 'i' or 's' modifier after the value overrides the default.
389	            boolean caseSensitive = quoted;
390	            if (!cq.isEmpty()) {
391	                String modifier = cq.consumeCssIdentifier();
392	                if (modifier.equalsIgnoreCase("s")) caseSensitive = true;
393	                else if (modifier.equalsIgnoreCase("i")) caseSensitive = false;
394	                else throw new Selector.SelectorParseException(
395	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, modifier + cq.remainder());
396	                cq.consumeWhitespace();
397	                if (!cq.isEmpty())
398	                    throw new Selector.SelectorParseException(
399	                        "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
400	            }
401	
402	            switch (op) {
403	                case "=":
404	                    eval = new Evaluator.AttributeWithValue(key, value, caseSensitive);
405	                    break;
406	                case "!=":
407	                    eval = new Evaluator.AttributeWithValueNot(key, value, caseSensitive);
408	                    break;
409	                case "^=":
410	                    eval = new Evaluator.AttributeWithValueStarting(key, value, caseSensitive);
411	                    break;
412	                case "$=":
413	                    eval = new Evaluator.AttributeWithValueEnding(key, value, caseSensitive);
414	                    break;
415	                case "*=":
416	                    eval = new Evaluator.AttributeWithValueContaining(key, value, caseSensitive);
417	                    break;
418	                default:
419	                    throw new Selector.SelectorParseException(
420	                        "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
421	            }
422	        }
423	        return eval;
424	    }
