361	        if (isEmpty()) throw new IllegalArgumentException("CSS identifier expected, but end of input found");
362	
363	        // Fast path for CSS identifiers that don't contain escape sequences.
364	        String identifier = reader.consumeMatching(TokenQueue::isIdent);
365	        char c = current();
366	        if (c != Esc && c != Unicode_Null) {
367	            // If we didn't end on an Esc or a Null, we consumed the whole identifier
368	            return identifier;
369	        }
370	
371	        // An escape sequence was found. Use a StringBuilder to store the decoded CSS identifier.
372	        StringBuilder out = StringUtil.borrowBuilder();
373	        if (!identifier.isEmpty()) {
374	            // Copy the CSS identifier up to the first escape sequence.
375	            out.append(identifier);
376	        }
377	
378	        while (!isEmpty()) {
379	            c = current();
380	            if (isIdent(c)) {
381	                out.append(consume());
382	            } else if (c == Unicode_Null) {
383	                // https://www.w3.org/TR/css-syntax-3/#input-preprocessing
384	                advance();
385	                out.append(Replacement);
386	            } else if (c == Esc) {
387	                advance();
388	                if (!isEmpty() && isNewline(current())) {
389	                    // Not a valid escape sequence. This is treated as the end of the CSS identifier.
390	                    reader.unconsume();
391	                    break;
392	                } else {
393	                    consumeCssEscapeSequenceInto(out);
394	                }
395	            } else {
396	                break;
397	            }
398	        }
399	        return StringUtil.releaseBuilder(out);
400	    }
401	
402	    private void consumeCssEscapeSequenceInto(StringBuilder out) {
403	        if (isEmpty()) {
404	            out.append(Replacement);
405	            return;
406	        }
407	
408	        char firstEscaped = consume();
409	        if (!StringUtil.isHexDigit(firstEscaped)) {
410	            out.append(firstEscaped);
411	        } else {
412	            reader.unconsume(); // put back the first hex digit
413	            String hexString = reader.consumeMatching(StringUtil::isHexDigit, 6); // consume up to 6 hex digits
414	            int codePoint;
415	            try {
416	                codePoint = Integer.parseInt(hexString, 16);
417	            } catch (NumberFormatException e) {
418	                throw new IllegalArgumentException("Invalid escape sequence: " + hexString, e);
419	            }
420	            if (isValidCodePoint(codePoint)) {
421	                out.appendCodePoint(codePoint);
422	            } else {
423	                out.append(Replacement);
424	            }
425	
426	            if (!isEmpty()) {
427	                char c = current();
428	                if (c == '\r') {
429	                    // Since there's currently no input preprocessing, check for CRLF here.
430	                    // https://www.w3.org/TR/css-syntax-3/#input-preprocessing
431	                    advance();
432	                    if (!isEmpty() && current() == '\n') advance();
433	                } else if (c == ' ' || c == '\t' || isNewline(c)) {
434	                    advance();
435	                }
436	            }
437	        }
438	    }
439	
440	    // statics below specifically for CSS identifiers:
441	
442	    // https://www.w3.org/TR/css-syntax-3/#non-ascii-code-point
443	    private static boolean isNonAscii(char c) {
444	        return c >= '\u0080';
445	    }
446	
447	    // https://www.w3.org/TR/css-syntax-3/#ident-start-code-point
448	    private static boolean isIdentStart(char c) {
449	        return c == '_' || StringUtil.isAsciiLetter(c) || isNonAscii(c);
450	    }
451	
452	    // https://www.w3.org/TR/css-syntax-3/#ident-code-point
453	    private static boolean isIdent(char c) {
454	        return c == Hyphen_Minus || StringUtil.isDigit(c) || isIdentStart(c);
455	    }
456	
457	    // https://www.w3.org/TR/css-syntax-3/#newline
458	    // Note: currently there's no preprocessing happening.
459	    private static boolean isNewline(char c) {
460	        return c == '\n' || c == '\r' || c == '\f';
461	    }
462	
463	    // https://www.w3.org/TR/css-syntax-3/#consume-an-escaped-code-point
464	    private static boolean isValidCodePoint(int codePoint) {
465	        return codePoint != 0 && Character.isValidCodePoint(codePoint) && !Character.isSurrogate((char) codePoint);
466	    }
467	
468	    private static final char[] CssIdentifierChars = {'-', '_'};
469	
470	    private String consumeEscapedCssIdentifier(char... matches) {
471	        StringBuilder sb = StringUtil.borrowBuilder();
472	        while (!isEmpty()) {
473	            char c = current();
474	            if (c == Esc) {
475	                advance();
476	                if (!isEmpty()) sb.append(consume());
477	                else break;
478	            } else if (matchesCssIdentifier(matches)) {
479	                sb.append(c);
480	                advance();
481	            } else {
482	                break;
483	            }
484	        }
485	        return StringUtil.releaseBuilder(sb);
486	    }
487	
488	    private boolean matchesCssIdentifier(char... matches) {
489	        return matchesWord() || reader.matchesAny(matches);
490	    }
491	
492	    /**
493	     Consume and return whatever is left on the queue.
494	     @return remainder of queue.
495	     */
496	    public String remainder() {
497	        return reader.consumeToEnd();
498	    }
499	
500	    @Override
501	    public String toString() {
502	        return reader.toString();
503	    }
504	
505	    @Override
506	    public void close() {
507	        reader.close(); // releases buffer back to pool
508	    }
509	}
