import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class Probe {
    static int pass = 0, fail = 0;

    static String html =
        "<div id=a data-v=' A B '></div>" +
        "<div id=b data-v='a=b'></div>" +
        "<div id=c data-v='AlphaBeta'></div>" +
        "<div id=d data-v=''></div>" +
        "<div id=e></div>";

    static void ids(String query, String expected) {
        Document doc = Jsoup.parse(html);
        String htmlBefore = doc.html();
        try {
            Elements els = doc.select(query);
            StringBuilder sb = new StringBuilder();
            for (var el : els) sb.append(el.id());
            String got = sb.toString();
            if (got.equals(expected)) { pass++; System.out.println("PASS " + query + " -> " + got); }
            else { fail++; System.out.println("FAIL " + query + " -> got [" + got + "] want [" + expected + "]"); }
        } catch (Selector.SelectorParseException e) {
            fail++; System.out.println("FAIL " + query + " -> threw " + e.getMessage());
        }
        if (!doc.html().equals(htmlBefore)) { fail++; System.out.println("FAIL doc mutated by " + query); }
    }

    static void throwsParse(String query) {
        Document doc = Jsoup.parse(html);
        String htmlBefore = doc.html();
        try {
            Elements els = doc.select(query);
            fail++; System.out.println("FAIL(expected throw) " + query + " -> returned " + els.size() + " els");
        } catch (Selector.SelectorParseException e) {
            pass++; System.out.println("PASS(throws) " + query);
        }
        if (!doc.html().equals(htmlBefore)) { fail++; System.out.println("FAIL doc mutated by " + query); }
        Elements els = doc.select("[data-v]");
        if (els.size() != 4) { fail++; System.out.println("FAIL doc broken after exception for " + query); }
    }

    public static void main(String[] args) {
        // quoted values with spaces / equals
        ids("[data-v=' A B ']", "a");
        ids("[data-v=\" A B \"]", "a");
        ids("[data-v='a=b']", "b");
        ids("[data-v=AlphaBeta]", "c");
        ids("[data-v=alphabeta]", "c"); // bare value case-insensitive
        ids("[data-v='']", "d");
        ids("[data-v]", "abcd");
        ids("[DATA-V=' A B ']", "a"); // key case-insensitive
        // negation
        ids("[data-v!=' A B ']", "bcde");
        ids("[data-v!=AlphaBeta]", "abde");
        // prefix case sensitivity
        ids("[data-v^=alpha]", "c");
        ids("[data-v^=alpha s]", "");   // case-sensitive same query must not hit
        ids("[data-v^=Alpha s]", "c");
        ids("[data-v^='Alpha']", "c");  // quoted default sensitive
        ids("[data-v^='alpha']", "");
        ids("[data-v^='alpha' i]", "c");
        ids("[data-v^=Alpha i]", "c");
        // suffix / contains / word(regex)
        ids("[data-v$=Beta]", "c");
        ids("[data-v*=phaB]", "c");
        ids("[data-v~=A.*B]", "ac");
        ids("[data-v ~= A.*B ]", "ac");
        // whitespace around operators
        ids("[ data-v = ' A B ' ]", "a");
        ids("[data-v != 'a=b']", "acde");
        ids("[data-v ^= AlphaBeta]", "c");
        ids("[data-v $= Beta]", "c");
        ids("[data-v *= lpha]", "c");
        // escapes in key
        ids("[data\\-v=' A B ']", "a");
        ids("[data\\2d v=' A B ']", "a");
        ids("[\\64 ata-v=' A B ']", "a");
        // escapes in values
        ids("[data-v=' A\\20 B ']", "a");
        ids("[data-v=a\\3d b]", "b");        // hex escape with terminating space -> a=b
        ids("[data-v='a\\=b']", "b");
        ids("[data-v=a\\=b]", "b");          // simple escape of = in bare value
        ids("[data-v=Alpha\\42 eta]", "c");  // \42<space> -> B
        ids("[data-v=\\20 A\\20 B\\20 ]", "a"); // hex-escaped spaces in bare value
        ids("[data-v=a\\3db]", "");          // \3db is a single codepoint, not a=b
        // errors
        throwsParse("[data-v=' A B '");
        throwsParse("[data-v");
        throwsParse("[data-v=");
        throwsParse("[data-v=foo bar]");
        throwsParse("[data-v= A B ]");
        throwsParse("[data-v=AlphaBeta q]");
        throwsParse("[data-v=AlphaBeta i i]");
        throwsParse("[data-v i=AlphaBeta]");
        throwsParse("[data-v=AlphaBeta i x]");
        throwsParse("[data-v='unclosed]");
        throwsParse("[data-v=abc\\]");
        throwsParse("[data-v=x\\ ]");
        throwsParse("[data-v\\]");
        throwsParse("[data-v=AlphaBeta]extra");
        throwsParse("[data-v=a\\3d  b]"); // two spaces: second one is junk
        // quoted empty
        ids("[data-v=\"\"]", "d");
        // quoted value keeps quotes and decoded backslashes
        Document d2 = Jsoup.parse("<p id=1 data-v='a\"b'></p><p id=2 data-v=\"a'b\"></p><p id=3 data-v='x\\y'></p>");
        if (d2.select("[data-v='a\"b']").size() == 1) pass++; else { fail++; System.out.println("FAIL quote in quoted"); }
        if (d2.select("[data-v=\"a'b\"]").size() == 1) pass++; else { fail++; System.out.println("FAIL squote in quoted"); }
        if (d2.select("[data-v='x\\\\y']").size() == 1) pass++; else { fail++; System.out.println("FAIL decoded backslash"); }

        System.out.println("\nPASS=" + pass + " FAIL=" + fail);
    }
}

