import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class Probe2 {
    static int pass=0, fail=0;
    static void check(boolean cond, String msg) {
        if (cond) { pass++; System.out.println("PASS " + msg); }
        else { fail++; System.out.println("FAIL " + msg); }
    }
    public static void main(String[] args) {
        Document doc = Jsoup.parse(
            "<div id=a data-v=' A B '></div>" +
            "<div id=b data-v='a=b'></div>" +
            "<div id=c data-v='AlphaBeta'></div>" +
            "<div id=d data-v=''></div>" +
            "<div id=e></div>" +
            "<div id=f data-v='a]'></div>" +
            "<div id=g data-v='x\\y'></div>");

        // escaped closing bracket inside a bare value
        check(doc.select("[data-v=a\\]]").size() == 1 && doc.select("[data-v=a\\]]").first().id().equals("f"),
            "escaped ] in bare value matches a]");
        // decoded backslash in a quoted value
        check(doc.select("[data-v='x\\\\y']").size() == 1, "quoted decoded backslash");
        // quoted value keeps equals sign
        check(doc.select("[data-v='a=b']").first().id().equals("b"), "quoted = exact");
        // existence selector still works on escaped key
        check(doc.select("[\\64 ata-v]").size() == 5, "existence via escaped key");
        // word (regex) matching semantics unchanged
        check(doc.select("[data-v~=A.*B]").size() == 2, "regex ~= unchanged");
        // document order, no duplicates
        Elements all = doc.select("[data-v]");
        StringBuilder ids = new StringBuilder();
        all.forEach(e -> ids.append(e.id()));
        check(ids.toString().equals("abcdf"), "document order, no dups: " + ids);
        // error queries all throw SelectorParseException, doc still works after
        String[] bad = {"[data-v=a\\]]extra", "[data-v='x", "[data-v='x\\'", "[data-v=", "[data-v^=",
            "[data-v=x\\ y]", "[data-v='a' s s]", "[data-v='a' g]", "[data-v s='a']", "[data-v='a']x",
            "[data-v=a\\3d  b]", "div[id=a][data-v"};
        for (String q : bad) {
            boolean threw = false;
            try { doc.select(q); } catch (Selector.SelectorParseException ex) { threw = true; }
            check(threw, "parse error for: " + q);
        }
        // doc structure intact after every error
        check(doc.html().contains("data-v=\" A B \"") || doc.html().contains("data-v=' A B '") || doc.html().contains(" A B "), "doc html intact");
        check(doc.select("[data-v='a=b']").size() == 1, "valid query still works after errors");
        // !='a=b' hits other values, empty, and missing; excludes exact equal
        StringBuilder notIds = new StringBuilder();
        doc.select("[data-v!='a=b']").forEach(e -> notIds.append(e.id()));
        check(notIds.toString().equals("acdeg"), "!= exact complement incl empty & missing: " + notIds);
        System.out.println("\nPASS=" + pass + " FAIL=" + fail);
    }
}
